// Blink — the "hello world" of Arduino.
// Turns the on-board LED (pin 13) on and off every half second.

void setup() {
  pinMode(LED_BUILTIN, OUTPUT);
}

void loop() {
  digitalWrite(LED_BUILTIN, HIGH);
  delay(500);
  digitalWrite(LED_BUILTIN, LOW);
  delay(500);
}

// HelloSerial — print a greeting and a running counter over USB serial.
// Open the Serial Monitor at 115200 baud.

unsigned long counter = 0;

void setup() {
  Serial.begin(115200);
  Serial.println("Hello from Bitbench!");
}

void loop() {
  Serial.print("tick ");
  Serial.print(counter++);
  Serial.print("  uptime(ms)=");
  Serial.println(millis());
  delay(1000);
}

// Fade — PWM brightness ramp on pin 9 using analogWrite().
// Wire an LED + 220 ohm resistor from pin 9 to GND (the virtual board has one).

int brightness = 0;
int step = 5;

void setup() {
  pinMode(9, OUTPUT);
}

void loop() {
  analogWrite(9, brightness);
  brightness += step;
  if (brightness <= 0 || brightness >= 255) {
    step = -step;
  }
  delay(20);
}

// SinePlotter — stream two waves for the Serial Plotter tab.
// Each line is "name:value name:value" which the plotter turns into series.

float phase = 0.0;

void setup() {
  Serial.begin(115200);
}

void loop() {
  Serial.print("sin:");
  Serial.print(sin(phase) * 100.0);
  Serial.print(" cos:");
  Serial.println(cos(phase) * 50.0);
  phase += 0.15;
  if (phase > TWO_PI) phase -= TWO_PI;
  delay(30);
}

// EchoUppercase — read what you type in the Serial Monitor and send it
// back in UPPERCASE. Also toggles the LED for every line received.

bool led = false;

void setup() {
  Serial.begin(115200);
  pinMode(LED_BUILTIN, OUTPUT);
  Serial.println("Type something and press Send...");
}

void loop() {
  while (Serial.available() > 0) {
    char c = Serial.read();
    if (c >= 'a' && c <= 'z') c = c - 'a' + 'A';
    Serial.print(c);
    if (c == '\n') {
      led = !led;
      digitalWrite(LED_BUILTIN, led ? HIGH : LOW);
    }
  }
}

// SerialCommands — control the LED by typing commands in the Serial Monitor.
// Uses the full Arduino core (String, readStringUntil, toInt).
//   on | off | blink <times> | status

int blinks = 0;

void setup() {
  Serial.begin(115200);
  pinMode(LED_BUILTIN, OUTPUT);
  Serial.println(F("Commands: on, off, blink <n>, status"));
}

void loop() {
  if (Serial.available()) {
    String cmd = Serial.readStringUntil('\n');
    cmd.trim();
    cmd.toLowerCase();
    if (cmd == "on") {
      digitalWrite(LED_BUILTIN, HIGH);
      Serial.println("LED is ON");
    } else if (cmd == "off") {
      digitalWrite(LED_BUILTIN, LOW);
      Serial.println("LED is OFF");
    } else if (cmd.startsWith("blink")) {
      int n = cmd.substring(5).toInt();
      if (n <= 0) n = 3;
      for (int i = 0; i < n; i++) {
        digitalWrite(LED_BUILTIN, HIGH);
        delay(150);
        digitalWrite(LED_BUILTIN, LOW);
        delay(150);
      }
      blinks += n;
      Serial.println("Blinked " + String(n) + " times (total " + String(blinks) + ")");
    } else if (cmd == "status") {
      Serial.print("uptime ");
      Serial.print(millis() / 1000.0, 1);
      Serial.println(" s");
    } else if (cmd.length()) {
      Serial.println("Unknown command: " + cmd);
    }
  }
}

// TrafficLight — a little state machine driving three LEDs.
// Red on pin 12, yellow on pin 11, green on pin 10.

const int RED = 12;
const int YELLOW = 11;
const int GREEN = 10;

void show(int r, int y, int g) {
  digitalWrite(RED, r);
  digitalWrite(YELLOW, y);
  digitalWrite(GREEN, g);
}

void setup() {
  pinMode(RED, OUTPUT);
  pinMode(YELLOW, OUTPUT);
  pinMode(GREEN, OUTPUT);
  Serial.begin(115200);
}

void loop() {
  Serial.println("GREEN");
  show(LOW, LOW, HIGH);
  delay(2000);
  Serial.println("YELLOW");
  show(LOW, HIGH, LOW);
  delay(700);
  Serial.println("RED");
  show(HIGH, LOW, LOW);
  delay(2000);
}

// KnightRider — a scanning light across pins 2..8.

const int FIRST = 2;
const int LAST = 8;

void setup() {
  for (int p = FIRST; p <= LAST; p++) pinMode(p, OUTPUT);
}

void light(int pin) {
  digitalWrite(pin, HIGH);
  delay(70);
  digitalWrite(pin, LOW);
}

void loop() {
  for (int p = FIRST; p <= LAST; p++) light(p);
  for (int p = LAST - 1; p > FIRST; p--) light(p);
}
